import{_ as t,a as o,o as d,a6 as r}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Get Customer Invoice","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-customer-invoice","title":"Get Single Customer Invoice","description":"Retrieve details of a specific customer invoice by ID.","request":"GET /api/shop/customer-invoices/1\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 5,\\n  \\"incrementId\\": \\"5\\",\\n  \\"state\\": \\"paid\\",\\n  \\"emailSent\\": true,\\n  \\"totalQty\\": 1,\\n  \\"orderCurrencyCode\\": \\"USD\\",\\n  \\"subTotal\\": 24.99,\\n  \\"baseSubTotal\\": 24.99,\\n  \\"grandTotal\\": 34.99,\\n  \\"baseGrandTotal\\": 34.99,\\n  \\"shippingAmount\\": 10,\\n  \\"baseShippingAmount\\": 10,\\n  \\"taxAmount\\": 0,\\n  \\"baseTaxAmount\\": 0,\\n  \\"discountAmount\\": 0,\\n  \\"baseDiscountAmount\\": 0,\\n  \\"shippingTaxAmount\\": 0,\\n  \\"baseShippingTaxAmount\\": 0,\\n  \\"subTotalInclTax\\": 24.99,\\n  \\"baseSubTotalInclTax\\": 24.99,\\n  \\"shippingAmountInclTax\\": 10,\\n  \\"baseShippingAmountInclTax\\": 10,\\n  \\"reminders\\": 0,\\n  \\"createdAt\\": \\"2026-07-21T17:58:29+05:30\\",\\n  \\"updatedAt\\": \\"2026-07-21T17:58:30+05:30\\",\\n  \\"downloadUrl\\": \\"https://yourstore.com/api/shop/customer-invoices/5/pdf\\",\\n  \\"items\\": [\\n    \\"/api/customer_invoice_items/11\\"\\n  ],\\n  \\"addresses\\": [\\n    \\"/api/customer_invoice_addresses/210\\",\\n    \\"/api/customer_invoice_addresses/211\\"\\n  ]\\n}\\n","commonErrors":[{"error":"404 Not Found","cause":"Invoice with specified ID does not exist or does not belong to the customer","solution":"Verify the invoice ID and ensure it belongs to the authenticated customer's orders"},{"error":"401 Unauthorized","cause":"Missing or invalid Bearer token","solution":"Login and provide a valid customer authentication token"},{"error":"403 Forbidden","cause":"Storefront key is missing or invalid","solution":"Provide a valid X-STOREFRONT-KEY header"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customer-invoices/get-customer-invoice.md","filePath":"api/rest-api/shop/customer-invoices/get-customer-invoice.md","lastUpdated":1787290888000}`),a={name:"api/rest-api/shop/customer-invoices/get-customer-invoice.md"};function s(i,e,n,c,l,h){return d(),o("div",null,e[0]||(e[0]=[r('<h1 id="get-customer-invoice" tabindex="-1">Get Customer Invoice <a class="header-anchor" href="#get-customer-invoice" aria-label="Permalink to &quot;Get Customer Invoice&quot;">​</a></h1><p>Retrieve detailed information for a specific customer invoice by its ID. Customers can only access invoices from their own orders — requesting another customer&#39;s invoice returns a 404, preventing enumeration attacks.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/customer-invoices/{id}</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>Customer invoice ID</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>One invoice, flat. The field set is identical to a row of <a href="/api/rest-api/shop/customer-invoices/get-customer-invoices.html">Get Customer Invoices</a> — there is no extra detail on this endpoint.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Invoice ID.</td></tr><tr><td><code>incrementId</code></td><td>string</td><td>Invoice number shown to the customer.</td></tr><tr><td><code>state</code></td><td>string</td><td><code>pending</code>, <code>pending_payment</code>, <code>paid</code>, or <code>overdue</code>.</td></tr><tr><td><code>emailSent</code></td><td>boolean</td><td>Whether the invoice email has gone out.</td></tr><tr><td><code>totalQty</code></td><td>integer</td><td>Units covered by this invoice.</td></tr><tr><td><code>orderCurrencyCode</code></td><td>string</td><td>Currency the order was placed in.</td></tr><tr><td><code>subTotal</code> / <code>baseSubTotal</code> / <code>subTotalInclTax</code> / <code>baseSubTotalInclTax</code></td><td>float</td><td>Line total, before and including tax.</td></tr><tr><td><code>grandTotal</code> / <code>baseGrandTotal</code></td><td>float</td><td>Invoice total.</td></tr><tr><td><code>shippingAmount</code> / <code>baseShippingAmount</code> / <code>shippingAmountInclTax</code> / <code>baseShippingAmountInclTax</code></td><td>float</td><td>Shipping charged.</td></tr><tr><td><code>taxAmount</code> / <code>baseTaxAmount</code> / <code>shippingTaxAmount</code> / <code>baseShippingTaxAmount</code></td><td>float</td><td>Tax charged.</td></tr><tr><td><code>discountAmount</code> / <code>baseDiscountAmount</code></td><td>float</td><td>Discount applied.</td></tr><tr><td><code>reminders</code></td><td>integer</td><td>Payment reminders sent so far.</td></tr><tr><td><code>downloadUrl</code></td><td>string</td><td>Absolute URL of the PDF. It still requires both auth headers, so it is a request URL rather than a shareable link.</td></tr><tr><td><code>items</code> / <code>addresses</code></td><td>array</td><td>References to the invoice lines and the order&#39;s addresses.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><p>The invoiced line items are available from the parent order&#39;s <code>items</code> block on <a href="/api/rest-api/shop/customer-orders/get-customer-order.html">Get Customer Order</a>, and on the invoice PDF. Over GraphQL the <code>customerInvoice</code> query returns them as selectable nested objects.</p><h2 id="error-responses" tabindex="-1">Error Responses <a class="header-anchor" href="#error-responses" aria-label="Permalink to &quot;Error Responses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Body <code>detail</code></th><th>Cause</th></tr></thead><tbody><tr><td><code>404</code></td><td><code>Customer invoice with ID &quot;999999&quot; not found</code></td><td>No such invoice, <strong>or</strong> it belongs to another customer&#39;s order. The two cases are deliberately indistinguishable.</td></tr><tr><td><code>403</code></td><td><code>Unauthenticated. Please login to perform this action</code></td><td>No customer Bearer token was sent.</td></tr><tr><td><code>401</code></td><td>—</td><td>The storefront key header was missing or wrong.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Invoice detail screen</strong> — read one invoice by the <code>id</code> carried in the list, and offer the PDF from <code>downloadUrl</code>.</li><li><strong>Payment-status check</strong> — re-read after an offline payment to see <code>state</code> move from <code>pending_payment</code> to <code>paid</code>.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Fetch the list instead when showing several invoices</strong> — this endpoint returns no more fields than a list row, so per-invoice calls add nothing.</li><li><strong>Read the line items from the parent order</strong> — the order detail carries them in full.</li><li><strong>Treat <code>404</code> as &quot;not yours or not there&quot;</strong> — the message quotes the requested ID and is not proof the invoice is missing store-wide.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customer-invoices/get-customer-invoices.html">Get All Customer Invoices</a> — every invoice raised against the customer&#39;s orders</li><li><a href="/api/rest-api/shop/customer-invoices/download-customer-invoice-pdf.html">Download Invoice PDF</a> — the invoice as a PDF stream</li><li><a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a> — the customer&#39;s order history</li><li><a href="/api/rest-api/shop/customers/get-customer-profile.html">Get Customer Profile</a> — read the authenticated customer&#39;s account details</li></ul>',20)]))}const m=t(a,[["render",s]]);export{p as __pageData,m as default};
